RESERVED_PATH = ".ssh/authorized_keys"

type Listed = list[DotfileListItem]
type Answer = DeleteDotfileResponse | GetDotfileResponse | Listed


@dataclass(frozen=True)
class CreatingAConfigFile(When[AUserAndTheirOwnConfig, AutoGeneratedFileAdapter, Answer]):
    """자기 auto-generated file 하나를 만든다."""

    @override
    def operation(self) -> str:
        return "create_default_auto_generated_file"

    @override
    def describe(self, laid: AUserAndTheirOwnConfig) -> str:
        return Says(
            f"{laid.owner.username}이 자기 auto-generated file 을 하나 만듭니다",
            english=f"{laid.owner.username} writes one of their own auto-generated files",
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: AUserAndTheirOwnConfig) -> Answer:
        with ActingAs(laid.owner):
            return await adapter.create_default_auto_generated_file(
                CreateAutoGeneratedFileInput(
                    owner=UserID(laid.owner.id),
                    creator_id=UserID(laid.owner.id),
                    path=CONFIG_PATH,
                    perm=CONFIG_PERMISSION,
                    data=CONFIG_DATA,
                )
            )


