@dataclass(frozen=True)
class TheFileIsWritten(Then[AUserAndTheirOwnConfig, Answer]):
    """만든 파일의 path, 권한, 내용이 응답으로 온다."""

    @override
    def says(self) -> str:
        return Says(
            "만든 파일의 path, 권한, 내용이 그대로 응답으로 옵니다",
            english="the path, permission and content of the file written come back as is",
        )

    @override
    def look(self, laid: AUserAndTheirOwnConfig, answered: Answered[Answer]) -> list[Verdict]:
        response = answered.response
        if response is None:
            return [MissingResponse(answered.raised)]
        if not isinstance(response, GetDotfileResponse):
            return [Same("response", type(response).__name__, "GetDotfileResponse")]
        return [
            Same("path", response.path, CONFIG_PATH),
            Same("perm", response.perm, CONFIG_PERMISSION),
            Same("data", response.data, CONFIG_DATA),
        ]


@dataclass(frozen=True)
class OnlyTheDefaultFileIsListed(Then[AUserAndTheirOwnConfig, Answer]):
    """default 로 지정된 파일만 그 가장 마지막 revision 의 내용과 함께 목록에 온다."""

    @override
    def says(self) -> str:
        return Says(
            f"default 로 지정된 {CONFIG_PATH} 파일만 가장 마지막 revision 의 내용과 함께 목록에 옵니다",
            english=f"only the {CONFIG_PATH} file set as default is listed, with its last revision's content",
        )

    @override
    def look(self, laid: AUserAndTheirOwnConfig, answered: Answered[Answer]) -> list[Verdict]:
        listed = answered.response
        if listed is None:
            return [MissingResponse(answered.raised)]
        if not isinstance(listed, list):
            return [Same("response", type(listed).__name__, "list")]
        return [
            Same(
                "files",
                [(one.path, one.permission, one.data) for one in listed],
                [(CONFIG_PATH, CONFIG_PERMISSION, CONFIG_DATA)],
            )
        ]


