type ConfigStep = Scenario[
    TestSeedingSession, AUserAndTheirOwnConfig, AutoGeneratedFileAdapter, Answer
]


@dataclass(frozen=True)
class AUserWritesTheirOwnConfigFile(
    Scenario[TestSeedingSession, AUserAndTheirOwnConfig, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-create-and-update-on-their-auto-generated-files-writes-one"

    @override
    def describe(self) -> str:
        return Says(
            "자기 auto-generated file 에 CREATE 와 UPDATE 를 받은 사용자가 auto-generated file 을 만들면, "
            "빈 응답이 오고, 그 파일은 내용을 revision 1 로 갖고 그 경로의 default 로 지정됩니다",
            english=(
                "when a user holding CREATE and UPDATE on their own auto-generated files writes one, an "
                "empty response comes back, and the file holds its content as revision 1 and is "
                "set as the default of its path"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, AUserAndTheirOwnConfig]:
        return SomeoneWithTheirOwnConfig(permissions=(Permission.CREATE, Permission.UPDATE))

    @override
    def when(self) -> When[AUserAndTheirOwnConfig, AutoGeneratedFileAdapter, Answer]:
        return CreatingAConfigFile()

    @override
    def then(self) -> Then[AUserAndTheirOwnConfig, Answer]:
        return TheFileIsWritten()


