SCENARIOS: list[ConfigStep] = [
    AUserWritesTheirOwnConfigFile(),
    AUserGrantedNothingMayNotWriteAConfigFile(),
    AConfigFileInAReservedPlaceIsRefused(),
    AUserListsOnlyTheirDefaultConfigFiles(),
    AUserGrantedNothingMayNotListConfigFiles(),
    AUserReadsTheirDefaultConfigFile(),
    AConfigFileThatIsNotDefaultIsNotFound(),
    AUserGrantedNothingMayNotReadAConfigFile(),
    AUserUpdatesTheirDefaultConfigFile(),
    UpdatingAConfigFileThatIsNotDefaultIsNotFound(),
    AUserGrantedNothingMayNotUpdateAConfigFile(),
    AUserDeletesTheirDefaultConfigFile(),
    DeletingAConfigFileThatIsNotDefaultIsNotFound(),
    AUserGrantedNothingMayNotDeleteAConfigFile(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_config_files(
    scenario: ConfigStep,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
    match scenario:
        case AUserWritesTheirOwnConfigFile():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, CONFIG_PERMISSION, True, [(1, CONFIG_DATA)])
            ]
        case AUserUpdatesTheirDefaultConfigFile():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, UPDATED_PERMISSION, True, [(1, CONFIG_DATA), (2, UPDATED_DATA)])
            ]
        case AUserDeletesTheirDefaultConfigFile():
            assert await config_files_left(engine) == []
